marks = [96, 90, 75, 60, 59]
for mark in marks:
    if mark >= 90:
        grade = "A"
    elif mark >= 75:
        grade = "B"
    elif mark >= 60:
        grade = "C"
    else:
        grade = "Fail"
    print(f"{mark}: {grade}")
